    "description": "GONZALEZ KELLY, AGUSTÍN FITTIPALDI 48 - The Speaking Dead Woman En un pueblo bonaerense, Espanto vuelve de la muerte para ayudar a su amiga Consuelo a salvar la peluquería en crisis. Sin clientas, inventan una pelumóvil. Entre chismes y cortes, el local se transforma en refugio y acto de resistencia. Dos actrices fenomenales, gran timing cómico, guion escrito con esmero (hay líneas de diálogo extraordinarias): 48 - La muerta que habla es una comedia de viejos que explora el costumbrismo y lo explota de una manera única. Los obstáculos de tipo jurídicos con los que se encuentra alguien que vuelve de la muerte ya han sido transitados, pero no dejan de tener su efecto. La amistad entre las dos señoras está tratada sin remilgos ni ternuras empalagosas. Por el contrario, el esmerado aspecto cómico de la película se basa en un desapego esencial, a resguardo de las lágrimas o la comodidad del viejismo. Sin emociones fáciles ni condescendencia, lo que queda es la desazón profunda, encarada con adultez, de la cercanía de la muerte.",
