    "description": "Sofía encuentra en su nueva casa una caja con varios casetes apilados. Decidida a comprobar si se acaba de mudar a un antro de fantasmas, llama a sus mejores amigas, Camila y Verónica, para pasar juntas una peculiar noche de chicas. Una historia de terror es, ante todo, un relato, un cuentito que escuchamos en reuniones en medio de la noche. 99 fantasmas empieza de manera similar, aunque en pleno día, con audios que nos ponen en la piel de ese personaje principal que se aterra ante lo que escucha. De esta forma, este cortometraje continúa la tradición del relato oral que pasa de generación en generación, pero desde una mirada consciente de un realizador que entendió el género y juega con él, usando referencias y momentos de humor que cortan el terror. Y, sobre todo, mediante el uso —y la ausencia— del sonido para construir aquel clima aterrador que remite al cine que viene realizando James Wan. A veces solo necesitás dos espacios y pocos actores para generar julepe, como en un cuentito de terror ideal para la noche.",
