    "description": "The Passion According to G.H.B. / La pasión según G.H.B. Un encuentro íntimo se expande inesperadamente y empuja a Matías a revisar viejos vínculos, fantasías y decisiones por venir, en una odisea queer nocturna donde lo real y lo imaginario se entrelazan. Con Clarice Lispector como guía un poco secreta, A paixão segundo G.H.B. está centrada en una escena casi primaria. Los levantes gay vía aplicaciones, con sus brevísimos cortejos, lo suficiente como para “entrar en clima”, y las lecturas de la Lispector, que parece oficiar como fondo intelectual al intercambio sexual. Dos hombres, luego tres hombres. El famoso trío se da en forma de comedia leve, como si el ceremonial del acto fuera en realidad un agregado de humor fatal con que los participantes se ven a sí mismos. Los directores ofrecen una muestra de pasiones un poco vacías, bañadas por la frialdad del encuentro rápido y por la premura de las despedidas, que quedan flotando en el aire con su carga de hastío y tristeza.",
