    "title_en": "Der Angriff des Alfred Edel auf sich selbst / El ataque",
    "description": "de Alfred Edel contra sí mismo A partir de fragmentos de films de Herzog, Kluge y otros, se traza un retrato de Alfred Edel, figura del Nuevo Cine Alemán. El montaje lo convierte en su propio interlocutor: lo vemos divagar sobre sexo, comida y muerte, siempre desmesurado y visionario. Jan Soldat, cineasta de los bordes, se centra en un actor centrífugo como Alfred Edel, que estuvo allí desde los inicios de Alexander Kluge. Ese allí, que incluyó al Nuevo Cine Alemán, derivó en muchas presencias en mucho cine y televisión desde mediados de los sesenta hasta los noventa del siglo XX. Actor de los que no pasaban desapercibidos, de una tradición gestual que no excluía la hipérbole y el absurdo, Edel hablaba pero a menudo vociferaba, con algo del rictus de Klaus Kinski cuando se ponía más intenso, nada menos. Edel, tantas veces actor secundario, se vuelve protagonista absoluto de este collage que lo tiene como tesis y antítesis de sí mismo, liderando el cartel de una fascinante supraficción cosida a cortes y también de su propia, inexorable y última realidad.",
