    "description": "llamando en un mal momento Criada en los 90, X hace bromas telefónicas de niña y termina trabajando en ventas durante su adolescencia. Olores de oficina, respiraciones pesadas y saludos vacíos la persiguen. A partir de material de archivo, el film explora la voz como mercancía sin rostro. Nadie va a extrañar al telemarketing, oficio detestado por igual a ambos lados del mostrador (o de la línea, más bien), cuando se extinga por fin junto a su cómplice primario, la telefonía fija. Pero si vamos a recordarlo, que sea como propone Martta Tuomaala: con una comedia rapidísima que baila en los objetos, las pantallas y las imágenes publicitarias; que se ríe de jefes y colegas, de los manuales absurdos y del propio nombre de la directora. La pista sobre la que Am I Calling You at a Bad Time baila y ríe está fabricada con retazos de la cultura audiovisual de fines del siglo XX, elegidos con una mezcla de humor seco y cariño que recuerda al cine del finés más famoso. Y donde suena al final, muy apropiadamente, un hitazo eurotechno compuesto para la ocasión.",
