    "description": "Un estudiante de cine, que niega estar enamorado de su profesora, se pregunta qué es el cine, qué es el amor y para qué hacemos lo que hacemos. Se trata de una fórmula conocida. Amor y cine no es lo mismo que amor por el cine, pero esta vez se juega con las palabras. Amor por la vida, amor por una profesora de cine. Amor por el cine a través de una persona que representa el cine. Con singular audacia, Julián Camilo Lloves dibuja un retrato en el que esas cuestiones, esos amores pueden conjugarse: retazos de la ciudad, equívocos afectivos, consciencia de tener entre manos un juego, nada menos que el del cine y la vida (asuntos en verdad inseparables). El director despliega su devoción cinéfila, juega con seriedad y comparte su pasión con el espectador. Mucho menos que una inclinación personal, un “gusto” como cualquier otro, el cine se toma seriamente, como una pasión amorosa que se impone de forma arrebatadora.",
