    "description": "OMING OF AGE - WORLD PREMIERE Eva, la mayor de tres hermanos, vive en la Villa 21-24 de Barracas. Dejó la escuela y sale a cartonear con su padre, Ramón. Mientras cuida a sus hermanos como si fuera su madre, atraviesa un cambio que transforma su vida. Esto es un cine verdadero, especialmente en sus fallos (si los hubiere), que no muestran otra cosa que la voluntad de contar algo, de decir cosas, de llegar a un acuerdo entre las voces de los barrios pobres y las instituciones. Cine “de tema” en su acepción más antigua, pero también cine como herramienta, o como vehículo en el que se expresan sueños de emancipación y de comunidad; como en el cine educativo en su versión más noble, tantas veces desacreditada. He aquí un inventario de interrogantes, de escasez, de fragilidad que alimentan las imágenes, siempre sin la menor sordidez ni evocaciones lastimeras de ningún tipo: Eva es cine en contra de ciertas fantasías burguesas de morbo y fascinación y a favor de su postulación como elemento de impulso y reafirmación vital. David Obarrio Eva, the eldest of three siblings, lives in Villa 21-24 in Barracas.",
