    "title": "Are We Monsters?",
    "title_en": "Xs̄ ūr / Asura",
    "description": "Filmado en Pattani, sur de Tailandia bajo ley marcial, el documental sigue a una familia inesperada: un docente de arte gay y radical, un musulmán y una madre soltera inestable. En una sociedad dividida, una nueva generación cuestiona la fe, la moral y el sentido de pertenencia. He aquí una pequeña maravilla, engañosamente simple y directa. Un retrato sin condescendencia de la temprana juventud tailandesa LGBT de origen musulmán en un clima de hostigamiento y Ley Marcial. Al modo de una película de reporte, los habitantes de Pattani revelan en su vida diaria un universo de dudas, deseos y transgresiones. Atrapados en medio de la mala fama regional como refugio del terrorismo y la proscripción que impone el credo heredado, los personajes sueñan su propia comunidad. La vida es dura, pero la narración nunca es lastimera, y en la disposición de las charlas entre los protagonistas o sus relatos en primera persona brilla la presencia de un cineasta de verdad. Lejos del cine etnográfico global, la película se ofrece como testigo de una sensibilidad aún por darse a conocer.",
