    "description": "Un escultor instala su taller en una zona rural y aislada de la costa gallega. Con el tiempo se aparta de todos, corta lazos con amigos y familia y empieza a imaginar otra identidad, hasta que un día el pasado vuelve a alcanzarlo. Esta película tiene un halo portugués en el paisaje, en la posibilidad de un cambio de vida, en la altivez de una historia que se construye con una paciencia infinita y una precisión para los detalles prácticamente asombrosa. Hay además una parte “literaria”, de texto, perfectamente ejecutada, con un guardia sabio y luego con la chica protagonista, hacia el final, en un plano fijo prodigioso que impugna el discurso del tipo con gran categoría. Asi chegou a noite sugiere siempre un tono de pregunta acerca del presente de esas vidas que están como en tránsito, un poco perdidas para sí mismas: la conciencia de ese estado de precariedad, que se despliega de a poco, como solo el cine sabe hacer con semejante refinamiento, resulta uno de los grandes aciertos de la película.",
