    "description": "MUNDIAL / PASSIONS - WORLD PREMIERE Mi gran noche Ana se encierra en su hotel favorito para pasar su cumpleaños número veintisiete. Ha decidido terminar con su vida y, antes de llevarlo a cabo, convoca a sus personas más cercanas para despedirse. Amparada en el nombre de una extraordinaria canción de Raphael, Mi gran noche despliega su mirada sobre el momento en el que una mujer decide suicidarse en la habitación de su hotel preferido. Antes de sellar su destino, convoca a aquellos que alguna vez amó para despedirse. Durante esas horas, por los diferentes espacios liminales del hotel, desfilan todo tipo de personajes: desde su expareja hasta un terapeuta que le insiste que espere al menos nueve años más para quitarse la vida. Lucas A. Vignale y Lorenzo Ferro observan de reojo, pero con mucho cariño, a cada uno de esos visitantes para trazar una elegía de los instantes finales, aquella marcada por el vértigo, los impulsos y los inevitables ajustes de cuentas con uno mismo.",
    "country": "Argentina",
    "year": "2026",
