    "title_en": "",
    "description": "sabe que en el infierno siempre es verano, y así comienza, creando círculos donde giran sus personajes (la travesura vacía, la tensión sexual vacía, la charla aristócrata vacía). Y de repente, a lo Fausto, el absurdo, malvado, se lleva todo a rincones insospechados: Buñuel en la pileta, Máxima velocidad masticada por perros asesinos y la seguridad francotiradora de Manoel de Oliveira haciendo pie. El mundo pensó que era una película de género, y es, como La idiocracia, una sátira que entiende que la pesadilla ya llegó y se parece demasiado a nuestros propios instintos animales. Juan Manuel Domínguez Three fierce dogs trap a group of young people in the pool of a luxurious house.",
