    "title": "Barrio triste",
    "title_en": "",
    "description": "En las afueras de Medellín, a fines de los 80, unos adolescentes roban la cámara de un reportero que investigaba luces extrañas en el cielo. Con ella registran su barrio y los inquietantes fenómenos que comienzan a rodearlos. En Barrio triste da toda la impresión de que estamos en presencia de un raro artefacto capaz de registrar el mundo conocido mientras se sugiere la existencia de otro. Hay una velocidad apabullante durante casi toda la película que va sumergiéndose en un final que es lírico,",
