    "description": ", hasta que se anime a entrar a este mundo. Binoche y sus montajistas (Sophie Brunet y Sophie Mandonnet) parecen seguir las inquietudes de Jean-Luc Godard en un famoso artículo: “Si dirigir es una mirada, montar es un latido del corazón. Prever está en la naturaleza de ambos; pero lo que uno busca prever en el espacio el otro lo busca en el tiempo.” Binoche se va casi dos décadas atrás y regresa con este fascinante retrato cercano del proceso creativo. Una película con pulso, con una actriz escandalosamente fotogénica, a la que la cámara y el montaje repatrian al cine desde otras artes.",
