    "title_en": "",
    "description": "narra un caso público de desastre, de siniestro, como dirían las compañías aseguradoras, con una eficacia sorprendente. Casi no hace falta decir más. Pero se puede añadir que la felicidad narrativa que se desprende de la película ha pasado a convertirse en el gran secreto olvidado de buena parte del cine contemporáneo.",
