    "description": "(Bafici ‘19). (1974, Budapest, Hungary). He graduated in Cinema from the Theater and Film Academy of Budapest in 2000. He has directed several features, among them Hukkle (2002, Bafici ‘03), Taxidermy (2006) and His Master’s Voice (Bafici ‘19). In a small rural community in Hungary, small scenes involving people and animals unfold almost wordlessly, while a barely perceptible crime quietly permeates everyday life.",
    "country": "Hungary",
