    "title_en": "",
    "description": "Soy Johnny el Curioso Retrato de Johnny Pigozzi, heredero, fotógrafo y coleccionista excéntrico, a través de imágenes y relatos que recorren su universo de lujo, amistades y curiosidades acumuladas a lo largo de los años. Julien Temple es el hombre que ama a sus retratados, aquel que tiene predilección por las ciudades, el rock, la historia y las historias. Esto lo sabemos desde siempre, pero con cada nueva película encontramos una rotunda confirmación. La",
