    "title": "La Limace et l’escargot",
    "title_en": "The Slug and the Snail / La babosa y el caracol",
    "description": "rotagoniza la propia Benhaïem: un choque de bastones con un hombre mayor termina con ambos caídos en la vereda y deriva en una singular invitación. Dos cuerpos inusuales instalados en la mesa de un café parisino, enfrentando la calle (y nuestra mirada) con sus copas de vino. Y luego una ficción mínima, y luminosa, capaz de transmitir una emoción genuina con un pijama compartido. Cuando Anne concluye el relato y les pregunta a las dos amigas por sus proyectos, el rostro de Pascale Bodet resplandece y la película nos invita a imaginar nuevas historias con una libertad asombrosa que diluye la distancia entre contar, filmar y vivir.",
