    "title_en": "à Versailles",
    "description": "presenta un relato, sí, de infancia; de gigante con sentimientos, de pasillos imposibles y nuevos, y de miedos convertidos en descubrimientos. Y sale ganando. Con un trazo en la tradición de la bande dessinée, la película convierte el escenario monumental del título en un territorio íntimo, de aventura pequeña y de educación sentimental. Los jardines y pasillos de Versailles dejan de ser un símbolo de la historia oficial para transformarse en un espacio de delicadeza y ligereza, y —fundamental— de amor por la mirada obstinadamente curiosa de su protagonista.",
