    "title": "Le Secret des mésanges",
    "title_en": "cantores",
    "description": ", de Antoine Lanciaux, aprovecha esa búsqueda infantil, esa impaciencia por crecer y aprender, para crear una aventura delicada, que vuelve maravilla la vida en la naturaleza y también la construcción de la memoria. La animación, hecha en papel recortado, genera la calidez lúdica desde una artesanía que se siente, como el verano, tangible y viva. Hay texturas, bosques y pasadizos; hay misterio, posibilidad de maravilla y pares. Y aparece el laberinto brillante y conmovedor que puede ser la historia de la propia familia, el saberse historia. Todo esto contado sin solemnidad, con una poesía que hace de la mirada curiosa la más terrenal de las magias.",
