    "description": "es más que eso, bastante más. En primer lugar, su frialdad es casi terrorífica; las detenciones abruptas, las resignadas caras obreras, los diálogos triviales: nada hace pensar en ella como el relato de un acontecimiento crucial. Por otro lado, la extraña belleza dentro del sentimiento de desesperanza con que son filmados los barrios proletarios; el clima desapacible, la grisura de la vida, la dignidad que consiste en estar en pantalla como si la cámara se hubiera introducido por la ventana. Menos que un thriller político, la película recoge con un efecto de verdad asombroso el devenir de un puñado de vidas lanzadas a la intemperie.",
