    "title": "No compteu amb els dits",
    "title_en": "",
    "description": "s Portabella busca una nueva forma de narrar y renuncia al modelo institucional de producción. Cuestiona el canon aristotélico, base del cine comercial y del espectáculo masivo del siglo XX, para abrir otras posibilidades de relato. Utilizando como estructura narrativa las normas técnicas del cine publicitario, este primer trabajo cinematográfico de Portabella sería impensable sin la poesía de Joan Brossa, con sus juegos de lenguaje, sus potentes metáforas visuales y su fascinación por las formas de representación populares. Portabella regresa del exilio tras el “escándalo Viridiana” y la primera frase de su primer film es: “Derrotado… pero no vencido”. La última secuencia deja al espectador clavado frente a la pantalla en blanco. Catálogo 2006 Portabella seeks a new form of storytelling and rejects the institutional model of production.",
