    "title": "No matar",
    "title_en": "Not to Kill",
    "description": "ill Un ensayo de memoria crítica sobre la violencia revolucionaria en la Argentina de los El modo imperativo del título no pertenece al campo de los signos de la retórica sino al de la ética. La posición de la película es clara. Se trata de testimonios; cosa sencilla a simple vista, pero para lograr esa condición diáfana hay que pensar y trabajar mucho la forma. Quienes tienen la palabra pertenecen en general al viejo funcionariato de las organizaciones armadas, que hablan a cámara, menos embarcados en una ceremonia de expiación que de recapitulación de sus propios actos, que semejan narraciones antiguas de un país alucinatorio. En verdad, la película es hipnótica: Villegas administra con una destreza apabullante los largos planos, las voces, los bellos y dolorosos interludios musicales con material de archivo, y convierte la experiencia de la primera persona en un relato sin coartadas ni excusas.",
