    "description": "Un adolescente hacker se integra a una red criminal, mueve millones y se entrega a una vida de excesos. Pero, antes de cumplir 17 años, un operativo de la Policía Federal lo obliga a enfrentar las consecuencias. Excesos y más excesos. El gran sueño (latino)americano. Hubo un tiempo que quizás fue hermoso, y la internet nos trajo una tribu ciberurbana difícil de entender para los ciudadanos de a pie. A principios de los 2000 los hackers pusieron patas para arriba nuestra precaria seguridad informática y se los creía capaces no solo de robarnos toda nuestra plata sino hasta de desatar la peor de las guerras mundiales. Esta es la historia, basada en un caso real, del Rey de la Internet de Brasil, o de cómo un adolescente logró vulnerar miles de cuentas bancarias y convirtió lo que para él era simple diversión en un delito federal que puso en alerta a un país entero. Y de cómo Latinoamérica también tuvo sus lobos, aunque no fueran de Wall Street.",
