    "title_en": "For Love We Carry On",
    "description": "es la historia de la sonidista de un centro cultural que es epicentro de una movida musical indie y hardcore, el relato mínimo de una piba precarizada en tiempos aciagos para la cultura, pero la película está al límite de la docuficción. Es que a las escenas actuadas se las acompaña con pasajes de bandas tocando, filmadas en planos cortos, desde el corazón mismo del pogo, y con entrevistas a distintos jóvenes que son parte de la movida, filmadas en nostálgico Mini DV. En las entrevistas sobrevuela la pregunta por la felicidad, cuando la crisis socioeconómica la hace impensable. Sin ningún derroche de candidez, la respuesta se encuentra en el gesto heroico de armar un recital, escribir un fanzine, producir un disco o, claro, filmar una película.",
