    "description": "e nada esperando capturarlo todo. El corto de Lucía Rovasio pasa del desgano a la tensión, del gimmick perezoso al cine. Filmada de frente, una pareja habla como si leyera líneas de diálogos. La conversación es pobre y circular, gira sobre sí misma y trata acerca del mundo escaso de los protagonistas (como si fuera uno de esos programas de streaming). Pero la situación se galvaniza de a poco con unos pillow shots que hubieran encantado a Ozu, y un cambio de escena lanza el corto hacia la geografía escarpada del drama. La pareja ahora se desintegra fatalmente bajo el peso de los secretos y los rencores. Rovasio filma y actúa el hundimiento serenamente, como alguien que contempla absorto su propio naufragio. Diego Maté A couple rehearses their argument.",
