    "title": "Robert Wilson and the CIVIL WarS",
    "title_en": "",
    "description": "al, un parásito se propaga entre los residentes y desata violencia e impulsos sexuales incontrolables, mientras un médico intenta detener el contagio antes de que sea demasiado tarde. Me gusta pensar que para ciertas películas uno debe saltar al vacío. Aceptar que el director tiene un microcosmos definido y que el pacto hay que hacerlo antes de entrar a la sala. Un poco a ciegas. Cronenberg pertenece a esa liga. Con él todo puede pasar. La metáfora sexual y social de Shivers parece simple y perturbadora, pero su cine jamás se queda ahí. Sus ideas se desplazan, mutan, se reproducen. Incluso se tornan escatológicas. Su cine es movedizo, como las larvas. Lo fascinante es que todo ocurre en un edificio nuevo, limpio, pensado como refugio para la clase media. Él lo toma y convierte el deseo en virus, el cuerpo en campo de batalla y deja flotando la sospecha de que debajo de la civilización siempre hay algo esperando moverse. Algo pequeño, viscoso, persistente. Como las larvas. Yummy.",
