    "title_en": "",
    "description": "ONES - PREMIERE MUNDIAL / PASSIONS - WORLD PREMIERE Durante una pequeña celebración entre tres compañeros de piso gays, la llegada de un joven contactado por una app de citas desestabiliza su intimidad y convierte el deseo en un juego peligroso de confianza. En la intimidad de la noche, bajo la luz tenue de un departamento vidriado, dos chicos esbeltos comparten confidencias, reflexiones, copas y caladas. La familiaridad entre ellos es evidente: viven juntos y son más amigos que amantes. Pero en medio de ese equilibrio aparece un tercero, más áspero y misterioso que el dúo inicial. El misterio es un arma de doble filo: esconde tanto como seduce. Lo que comienza como un relato cotidiano abre paso, con la paciencia de quien sabe adónde va, a un territorio más inquietante, un viraje de género que invita al avance de las sombras, tanto literal como figurativamente. Un diálogo con la historia reciente del cine de terror, en el que el sexo, el deseo y sus consecuencias siempre juegan un rol central.",
