    "title": "Salteadores nocturnos",
    "title_en": "Nocturnal Raiders",
    "description": "Durante el golpe de Estado de 1966 en Argentina, el despacho del presidente Arturo Illia es tomado por militares sublevados. Frente al avance de las Fuerzas Armadas, Illia enfrenta en soledad la ocupación de la Casa Rosada. En la tradición de films que narran la calma que antecede al huracán, sobre la que se inscriben Las horas más oscuras, Lincoln o Siete días de mayo, la obra del joven director y guionista Joaquín Ferrá pinta un lienzo sobre el momento exacto en que el presidente Arturo Illia finalizó su mandato a la fuerza. Con la noche como telón de fondo, las Fuerzas Armadas irrumpieron en su despacho. Allí, el presidente Illia (interpretado por el inmarcesible Mario Alarcón), acompañado de un grupo de colaboradores cercanos, mantuvo un duelo verbal con el general Julio Alsogaray. La tensión invadió sus cuerpos, el derrocamiento estaba consumándose y la democracia llegaba a su fin. A partir de ese instante se daba inicio a uno de los períodos más oscuros de la historia argentina.",
    "country": "Argentina",
    "year": "2026",
    "duration": "20'",
    "image": "https://bafici.org/wp-content/uploads/P257-cover.webp",
    "page": 266,
