    "title": "Shivers",
    "title_en": "",
    "description": "parece simple y perturbadora, pero su cine jamás se queda ahí. Sus ideas se desplazan, mutan, se reproducen. Incluso se tornan escatológicas. Su cine es movedizo, como las larvas. Lo fascinante es que todo ocurre en un edificio nuevo, limpio, pensado como refugio para la clase media. Él lo toma y convierte el deseo en virus, el cuerpo en campo de batalla y deja flotando la sospecha de que debajo de la civilización siempre hay algo esperando moverse. Algo pequeño, viscoso, persistente. Como las larvas. Yummy.",
