    "title": "Sí, cambio",
    "title_en": "Yes, Over",
    "description": ", esta distinguida película de pesquisa, esta comedia atenta siempre al desvarío como síntoma, opera entonces como dispensario de situaciones que se retraen, que se agazapan, que parecen respirar en la sombra esperando tomar la palabra. Feliz forma de antipelícula de detectives, tiene en María Villar y Tamara Leschner una carta ganadora: las reinas de la comedia hierática.",
