    "description": "Khake sar beh mohr / La tierra sellada En un entorno rural, una joven resiste el matrimonio arreglado que su familia intenta imponerle. Su negativa, leída como posesión demoníaca, revela un entramado de control y violencia sobre el cuerpo y la voluntad femenina. Rodada originalmente en 16 mm, la película narra lo que se ha dado en llamar “rebelión pasiva”, menos un gesto de franca confrontación que una negativa a convertirse en lo que no se desea. Una mujer de una localidad de provincia iraní no",
