    "description": "En una Navidad sofocante en Los Ángeles, Penny, obsesionada con su cuerpo, toma Thinestra, una droga similar al Ozempic. Tras una purga violenta, su carne desechada regresa convertida en Penelope, su doble voraz. Mientras el caos crece, Penny lucha por recuperar el control. Thinestra inscribe el terror en una genealogía donde el género funciona como reservorio de las ansiedades de su tiempo: aquí, la corporalidad como campo de batalla.",
