    "description": "es un cortometraje sobre mujeres de presos, pero Paolinelli advierte rápidamente que es mucho más que eso. Si bien no rehúye a interrogantes agotados por medios tradicionales, se libra de cada uno de los vicios formales del documental indolente para articular un relato coral con una búsqueda propia: explorar la intimidad negada, el amor fuera de los márgenes, la feminidad y los afectos que se configuran en un espacio suspendido, donde existe un no tiempo y un no lugar. Para lograrlo, la directora toma una decisión ética y estética y pone en primer plano los rostros de novias, madres y hermanas que, a su manera, exponen una realidad que hasta entonces apenas alcanzábamos a imaginar. En definitiva, hace cine. Alejandro Tévez Imprisonment as seen through the eyes of common criminals’ wives. Relationships, financial support, visits, waiting, emotional states. The opening text is eloquent.",
