    "title_en": "la puerta a un vampiro?",
    "description": "What Kind of Kid Opens the Door to a Vampire? Boom Boom Kid y Martiniano Zurita hallan un Super 8 perdido, Drácula en Campana. Vuelven a su ciudad para rastrear a sus autores. Entre archivo y música lo-fi surge una escena joven y artesanal que encendió el rock under argentino. Boom Boom Kid y su ópera prima confirman lo que siempre supimos: su capacidad, como diría David Obarrio, para “oír el latido de las cosas pequeñas, pequeñas, que confirman sus gustos”. Su Santo Grial en esta maravilla es el corto Drácula en Campana, de Titi Ramírez, un clásico de culto casero y latinoamericano, y BBK y pandilla salen a escuchar, capturar y respetar relatos que marcan una aventura —la de crear, la de ser joven, la del saber, la del capricho, la de no dejar que mueran las cosas que viven en nuestra sangre—. La hiperacción creativa de BBK se convierte aquí en una clase de cine, sobre cómo enamorarse de las cruces pasadas y presentes de otros, de la creatividad con y sin campanas, y de la ferocidad de saber que lo único feo es no tener por qué vivir.",
