    "title_en": "Silent Rebellion / El toro por las astas",
    "description": "Emma, de 15 años y embarazada luego de una violación, desafía a su represiva comunidad protestante para abrirse un camino propio. Mientras enfrenta la hipocresía del pueblo y la sombra de la Segunda Guerra, transforma el trauma en impulso de emancipación. Marie-Elsa Sgualdo irrumpe con una ópera prima y entiende que la rebeldía, a veces, empieza en silencio. Ambientada en el Jura suizo de 1943, À bras-le-corps convierte un paisaje pastoral casi caricaturesco —valles, iglesias protestantes, casas austeras— en el escenario de una guerra íntima donde una adolescente embarazada tras una violación decide no aceptar su destino seteado. Sgualdo filma ese despertar moral con una mezcla de delicadeza y firmeza, con la actriz Lila Gueneau logrando, al estilo del cine clásico, contener tormentas enteras. No hay aquí gesto grandilocuente sino una quirúrgica insurrección microscópica. Sgualdo se juega por una puesta en escena jane austera y sensorial, donde el drama gigante se filtra en los detalles: un rostro, una pausa, una emoción.",
